{
  "summary": "2022 Subaru Outback electrical system: intermittent touchscreen shutdown disables safety features/adaptive cruise/eyesight while driving; speakers blast loudly; power windows fail to raise.",
  "group": "electrical_general",
  "symptoms": [
    "touchscreen shuts down",
    "safety features shut off",
    "adaptive cruise shuts off while driving, causing deceleration",
    "eyesight shuts off",
    "keyboard controls unavailable",
    "screen reboot takes a minute or two",
    "speakers randomly blast very loud, startling and distracting occupants",
    "power windows occasionally fail to go back up and reverse partway through raising"
  ],
  "conditions": [
    "intermittent"
  ],
  "fault_codes": [],
  "safety_relevant": true,
  "missing_info": [
    "mileage"
  ],
  "clues": [
    {
      "kind": "component_group",
      "quote": "ELECTRICAL SYSTEM"
    },
    {
      "kind": "symptom",
      "quote": "The touchscreen shuts down and makes the safety features shut off."
    },
    {
      "kind": "condition",
      "quote": "now is happening a few times per month"
    },
    {
      "kind": "symptom",
      "quote": "Happens always while driving which causes the adaptive cruise to shut off, causing deceleration"
    },
    {
      "kind": "symptom",
      "quote": "the eyesight shuts off"
    },
    {
      "kind": "symptom",
      "quote": "the controls on the keyboard are not available"
    },
    {
      "kind": "symptom",
      "quote": "It takes a minute or two for the screen to reboot and safety features to re-engage"
    },
    {
      "kind": "safety",
      "quote": "this causes distraction and possible safety hazard"
    },
    {
      "kind": "symptom",
      "quote": "the speakers randomly will blast so loud it startles and distracts everyone in the car"
    },
    {
      "kind": "condition",
      "quote": "This seems to happen randomly, can be at start up, or after sound system has been in use."
    },
    {
      "kind": "symptom",
      "quote": "the power windows occasionally will not go back up"
    },
    {
      "kind": "symptom",
      "quote": "Thry reverse partway through raising."
    }
  ]
}

